const cards = $input.first().json.cards || [];
function tags(s){ return (s||'').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').trim(); }
function fracCents(seg){
  if(!seg) return null;
  const a0=seg.match(/aria-label="(?:Antes:s*)?([d.]+) reais(?: com (d+) centavos)?"/);
  if(a0){ const n=parseFloat(a0[1].replace(/./g,'')+'.'+(a0[2]?a0[2].padStart(2,'0'):'00')); if(!isNaN(n)) return n; }
  const f=seg.match(/andes-money-amount__fraction"[^>]*>([\d.]+)</);
  if(f){ const c=seg.match(/andes-money-amount__cents[^"]*"[^>]*>(\d+)</); const n=parseFloat(f[1].replace(/\./g,'')+'.'+(c?c[1]:'00')); if(!isNaN(n)) return n; }
  const a=seg.match(/aria-label="(?:Antes:\s*)?([\d.]+) reais(?: com (\d+) centavos)?"/);
  if(a){ const n=parseFloat(a[1].replace(/\./g,'')+'.'+(a[2]?a[2]:'00')); if(!isNaN(n)) return n; }
  return null;
}
const seen=new Set(); const out=[];
for(const raw of cards){
  const card = typeof raw==='string'? raw : ((raw&&raw.cards)||'');
  let url=null, mlb=null;
  const hrefs=[...card.matchAll(/href="([^"]+)"/g)].map(m=>m[1]);
  for(const h of hrefs){
    if(h.includes('click1')) continue;
    const mm=h.match(/MLB-?(\d{6,})/i);
    if(mm && /mercadolivre\.com\.br/.test(h)){ url=h.split('?')[0].split('#')[0]; mlb='MLB'+mm[1]; break; }
  }
  if(!url||!mlb||seen.has(mlb)) continue;
  seen.add(mlb);
  let title=null; const tm=card.match(/poly-component__title[^>]*>([\s\S]*?)<\/a>/); if(tm) title=tags(tm[1]).slice(0,500);
  let img=null; const im=card.match(/<img[^>]+(?:data-src|src)="(https:\/\/http2\.mlstatic\.com[^"]+)"/); if(im) img=im[1].split('?')[0];
  const work=card.replace(/<s [^>]*andes-money-amount--previous[\s\S]*?<\/s>/,'');
  const ci=work.indexOf('poly-price__current');
  // 18/Nov: 800 letras cortava antes dos centavos (R$ 30,89 saía R$ 30). Agora 2000 e lê o aria-label primeiro.
  const seg = ci>=0 ? work.slice(ci,ci+2000) : work;
  const price_current = fracCents(seg);
  const pm=card.match(/andes-money-amount--previous[\s\S]{0,800}/);
  let price_original = pm ? fracCents(pm[0]) : null;
  // gatilhos do card (nota, vendidos, % OFF, cupom do anúncio, entrega, loja oficial)
  const txt = tags(card.replace(/<[^>]+>/g,' | ')).replace(/\s+/g,' ');
  const promo = {};
  const rt = card.match(/Classifica[çc][ãa]o ([\d.,]+) de 5/i); if(rt) promo.rating = parseFloat(rt[1].replace(',','.'));
  const vd = card.match(/\+([\d.,]+\s*mil|[\d.,]+)\s*vendidos/i); if(vd) promo.vendidos = '+'+vd[1].replace(/\s+/g,'');
  const cp = card.match(/poly-coupons__pill[^>]*>([\s\S]*?)<\//); if(cp){ const t=tags(cp[1]); if(/cupom/i.test(t)) promo.cupom_anuncio=t; }
  const sh = (card.match(/poly-component__shipping[\s\S]{0,600}/)||[''])[0];
  if(/frete gr[aá]tis|chegar[aá] gr[aá]tis|envio gr[aá]tis/i.test(sh)) promo.frete_gratis = true;
  if(/amanh[ãa]/i.test(sh)) promo.chega_amanha = true;
  if(/aria-label="?[^"]*\bFULL\b|full_icon|fulfillment|ui-pb-highlight--full/i.test(card)) promo.full = true;
  if(/loja oficial/i.test(txt)) promo.loja_oficial = true;
  const dc = card.match(/(\d{1,2})%\s*OFF/); const discount_pct = dc ? +dc[1] : null;
  out.push({ mlb, url, title, image_url:img, price_current, price_original, promo, discount_pct });
  if(out.length>=10) break;
}
return [{ json: { produtos: out, total: out.length } }];

